const roundTube = function(configuration is map) returns Context
{
    const context = newContextWithDefaults();
    const s = newSketchOnPlane(context, makeId("profile"), { "sketchPlane" : plane(vector(0, 0, 0) * meter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s, "outer", { "center" : vector(0, 0) * millimeter, "radius" : 6 * millimeter });
    skCircle(s, "inner", { "center" : vector(0, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(s);
    return context;
};

function profileOf(build is function) returns PartStudioData
{
    return { "buildFunction" : build, "configuration" : {}, "partQuery" : qEverything(EntityType.BODY) } as PartStudioData;
}

// sketch: a ring and the square inside it, and a square apart
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "outer", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skRectangle(s1, "inner", { "firstCorner" : vector(5, 5) * millimeter, "secondCorner" : vector(15, 15) * millimeter });
    skRectangle(s1, "apart", { "firstCorner" : vector(30, 0) * millimeter, "secondCorner" : vector(40, 10) * millimeter });
    skSolve(s1);
    return { "sheets" : evaluateQueryCount(context, qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET)), "faces" : evaluateQueryCount(context, qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.FACE)), "regions" : evaluateQueryCount(context, qSketchRegion(id + "s1")) };
}

